import React, { useCallback, useEffect, useMemo, useState } from "react";
import axios from "axios";

function Card({ title, action, children }) {
  return (
    <div
      style={{
        background: "white",
        border: "1px solid #e2e8f0",
        borderRadius: 16,
        padding: 16,
      }}
    >
      <div
        style={{
          fontWeight: 900,
          marginBottom: 12,
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          gap: 12,
        }}
      >
        <div>{title}</div>
        {action}
      </div>
      {children}
    </div>
  );
}

const btnDark = {
  borderRadius: 12,
  border: "1px solid #0f172a",
  background: "#0f172a",
  color: "white",
  padding: "10px 12px",
  fontWeight: 900,
  cursor: "pointer",
};

const btnDanger = {
  borderRadius: 12,
  border: "1px solid #ef4444",
  background: "#ef4444",
  color: "white",
  padding: "10px 12px",
  fontWeight: 900,
  cursor: "pointer",
};

export default function TeacherDashboard() {
  const [students, setStudents] = useState([]);
  const [studentId, setStudentId] = useState("");
  const [rows, setRows] = useState([]);

  // create row
  const [course, setCourse] = useState("");

  // alerts
  const [isSuccess, setIsSuccess] = useState(false);
  const [isError, setIsError] = useState(false);
  const [successMessage, setSuccessMessage] = useState("");
  const [errorMessage, setErrorMessage] = useState("");

  const clearAlerts = () => {
    setIsSuccess(false);
    setIsError(false);
    setSuccessMessage("");
    setErrorMessage("");
  };

  const showSuccess = (msg) => {
    clearAlerts();
    setSuccessMessage(msg);
    setIsSuccess(true);
  };

  const showError = (msg) => {
    clearAlerts();
    setErrorMessage(msg);
    setIsError(true);
  };

  useEffect(() => {
    if (!isSuccess) return;
    const t = setTimeout(clearAlerts, 2500);
    return () => clearTimeout(t);
  }, [isSuccess]);

  // READ students
  const loadStudents = useCallback(async () => {
    try {
      const res = await axios.get("http://localhost:5000/students");
      setStudents(res.data || []);
      if (res.data?.length) setStudentId(res.data[0].id);
    } catch {
      showError("Failed to load students");
    }
  }, []);

  // READ dashboard
  const loadDashboard = useCallback(async () => {
    if (!studentId) return;
    try {
      const res = await axios.get(
        `http://localhost:5000/students/${studentId}/dashboard`
      );
      setRows(res.data.rows || []);
    } catch {
      showError("Failed to load dashboard");
    }
  }, [studentId]);

  useEffect(() => {
    loadStudents();
  }, [loadStudents]);

  useEffect(() => {
    loadDashboard();
  }, [loadDashboard]);

  // CREATE course
  const addCourse = async () => {
    if (!course.trim()) {
      showError("Course name is required");
      return;
    }

    try {
      await axios.post(`http://localhost:5000/students/${studentId}/courses`, {
        course,
      });
      showSuccess("Course added");
      setCourse("");
      loadDashboard();
    } catch {
      showError("Failed to add course");
    }
  };

  // UPDATE grade
  const updateGrade = async (course, grade) => {
    try {
      await axios.put(`http://localhost:5000/students/${studentId}/grade`, {
        course,
        grade,
      });
      loadDashboard();
    } catch {
      showError("Failed to update grade");
    }
  };

  // UPDATE absences
  const updateAbsences = async (course, absences_used) => {
    try {
      await axios.put(`http://localhost:5000/students/${studentId}/absences`, {
        course,
        absences_used,
      });
      loadDashboard();
    } catch {
      showError("Failed to update absences");
    }
  };

  // DELETE course
  const deleteCourse = async (course) => {
    try {
      await axios.delete(
        `http://localhost:5000/students/${studentId}/courses/${course}`
      );
      showSuccess("Course deleted");
      loadDashboard();
    } catch {
      showError("Failed to delete course");
    }
  };

  return (
    <div style={{ display: "grid", gap: 16 }}>
      <Card
        title="Teacher Dashboard"
        action={
          <button onClick={loadDashboard} style={btnDark}>
            Refresh
          </button>
        }
      >
        {(isSuccess || isError) && (
          <div
            style={{
              marginBottom: 12,
              borderRadius: 12,
              padding: "10px 12px",
              fontWeight: 800,
              background: isSuccess ? "#f0fdf4" : "#fff1f2",
              color: isSuccess ? "#166534" : "#991b1b",
              border: `1px solid ${isSuccess ? "#bbf7d0" : "#fecaca"}`,
            }}
          >
            {isSuccess ? successMessage : errorMessage}
          </div>
        )}

        <select
          value={studentId}
          onChange={(e) => setStudentId(e.target.value)}
          style={{
            border: "1px solid #e2e8f0",
            borderRadius: 12,
            padding: "10px 12px",
          }}
        >
          {students.map((s) => (
            <option key={s.id} value={s.id}>
              {s.id} — {s.Fname} {s.Lname}
            </option>
          ))}
        </select>
      </Card>

      <Card title="Add Course">
        <div style={{ display: "flex", gap: 10 }}>
          <input
            value={course}
            onChange={(e) => setCourse(e.target.value)}
            placeholder="Course name"
            style={{
              borderRadius: 12,
              border: "1px solid #e2e8f0",
              padding: "10px 12px",
              flex: 1,
            }}
          />
          <button onClick={addCourse} style={btnDark}>
            Add
          </button>
        </div>
      </Card>

      <Card title="Edit Grades & Absences">
        <div style={{ display: "grid", gap: 12 }}>
          {rows.map((r) => (
            <div
              key={r.course}
              style={{
                border: "1px solid #e2e8f0",
                borderRadius: 14,
                padding: 14,
              }}
            >
              <div style={{ display: "flex", justifyContent: "space-between" }}>
                <b>{r.course}</b>
                <button
                  onClick={() => deleteCourse(r.course)}
                  style={btnDanger}
                >
                  Delete
                </button>
              </div>

              <div
                style={{
                  marginTop: 10,
                  display: "grid",
                  gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))",
                  gap: 10,
                }}
              >
                <input
                  value={r.grade ?? ""}
                  placeholder="Grade"
                  onChange={(e) => updateGrade(r.course, e.target.value)}
                  style={{
                    borderRadius: 12,
                    border: "1px solid #e2e8f0",
                    padding: "10px 12px",
                  }}
                />

                <input
                  type="number"
                  value={r.absences_used}
                  onChange={(e) => updateAbsences(r.course, e.target.value)}
                  style={{
                    borderRadius: 12,
                    border: "1px solid #e2e8f0",
                    padding: "10px 12px",
                  }}
                />
              </div>
            </div>
          ))}
        </div>
      </Card>
    </div>
  );
}
